mapper.select:
	select * from (
	  select to_char(t.value_date,'yyyy-MM-dd') VALUEDATE, t.UNIT_VALUE PRDVALUE,t.UNIT_VALUE_T TOTALVALUE,t.UNIT_VALUE SGAMT, t.UNIT_VALUE SHAMT from REP_PROD_INDEX t
	  where t.prod_id = #{prodId}
		and t.value_date < #{endDate}
	    and t.status = 'E'
		and exists (
			  select 1 from CHB_MKT_HOLIDAY h where h.market_code = '04'
				and h.is_holiday = '0'
				and t.value_date = h.busi_date
		  )
	  order by t.value_date desc
  ) where rownum = 1

select * from (
  select to_char(t.value_date,'yyyy-MM-dd') cDate, to_char(nvl(t.UNIT_VALUE,0)) value, to_char(nvl(t.UNIT_VALUE_T,0)) totalValue
  from REP_PROD_INDEX t
  where t.prod_id = #{prodId}
	and t.value_date < #{endDate}
	and t.status = 'E'
	and exists (
	  select 1 from CHB_MKT_HOLIDAY h where h.market_code = '04'
	and h.is_holiday = '0'
	and t.value_date = h.busi_date
	  )
  order by t.value_date desc
) where rownum <= 30
